{"new_string": "// ===== MODE TOGGLE =====
function setMode(mode, silent) {
  currentMode = mode;
  localStorage.setItem('outreach-mode', mode);

  document.getElementById('modeTestBtn').className = 'mode-btn' + (mode === 'test' ? ' active-test' : '');
  document.getElementById('modeProdBtn').className = 'mode-btn' + (mode === 'production' ? ' active-prod' : '');
  const indicator = document.getElementById('modeIndicator');
  indicator.textContent = mode === 'test' ? '🧪 TEST MODE' : '🚀 PRODUCTION MODE';
  indicator.className = 'mode-indicator ' + (mode === 'test' ? 'test' : 'prod');

  // Show mock inbox only in test mode
  document.getElementById('mockInboxPanel').classList.toggle('show', mode === 'test');

  if (!silent) {
    loadMockInbox();
  }
}

// ===== MODAL =====
function openSendModal(leadId) {
  const lead = LEADS.find(l => l.id === leadId);
  if (!lead) return;
  currentAction = 'send';
  currentLeadId = leadId;
  const modeLabel = currentMode === 'test' ? '(Mock Inbox)' : '(Live Send)';
  document.getElementById('modalTitle').textContent = '📤 Confirm Send ' + modeLabel;
  document.getElementById('modalMessage').innerHTML = `Send outreach email to <strong>${lead.name}</strong> at <strong>${lead.email}</strong>?<br><br><span style="color:var(--text-secondary);font-size:12px;">${lead.notes}</span>`;
  const btn = document.getElementById('modalConfirmBtn');
  btn.textContent = currentMode === 'test' ? '🧪 Send to Mock Inbox' : '🚀 Send Live Email';
  btn.className = 'btn btn-confirm';
  document.getElementById('confirmModal').classList.add('show');
}

function openDeleteModal(leadId) {
  const lead = LEADS.find(l => l.id === leadId);
  if (!lead) return;
  currentAction = 'delete';
  currentLeadId = leadId;
  document.getElementById('modalTitle').textContent = '🗑 Confirm Delete';
  document.getElementById('modalMessage').innerHTML = `Remove <strong>${lead.name}</strong> from <strong>${lead.company}</strong>?<br><br><span style="color:var(--text-secondary);font-size:12px;">This cannot be undone, but the card will be hidden from this view.</span>`;
  const btn = document.getElementById('modalConfirmBtn');
  btn.textContent = '🗑 Delete';
  btn.className = 'btn btn-confirm-del';
  document.getElementById('confirmModal').classList.add('show');
}

function closeModal() {
  document.getElementById('confirmModal').classList.remove('show');
  currentAction = null;
  currentLeadId = null;
}

function executeAction() {
  if (currentAction === 'send' && currentLeadId) {
    const lead = LEADS.find(l => l.id === currentLeadId);
    if (!lead) { closeModal(); return; }

    // Call the API to advance lead and send email
    const pipelineMap = { 'Books': 'books', 'SaaS': 'saas', 'Consulting': 'consulting' };
    const pipeline = pipelineMap[lead.pipeline] || 'books';

    fetch(API_BASE + '/api/advance-lead', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        pipeline: pipeline,
        lead_name: lead.name,
        mode: currentMode,
        email: lead.email,
        subject: '[' + lead.pipeline + '] Following up with ' + lead.company,
        body: 'Hi ' + lead.name.split(' ')[0] + ',\n\nThanks for your interest in ' + lead.pipeline + '. I wanted to follow up on our conversation.\n\nBest,\nBob J Mills\nMIFECO'
      })
    })
    .then(r => r.json())
    .then(data => {
      if (data.success) {
        if (!sentIds.includes(currentLeadId)) {
          sentIds.push(currentLeadId);
          localStorage.setItem('outreach-sent', JSON.stringify(sentIds));
        }
        renderLeads();
        updateStats();
        loadMockInbox();
        closeModal();
      } else {
        alert('Error: ' + (data.error || 'Unknown error'));
      }
    })
    .catch(err => {
      alert('Network error: ' + err.message);
    });

  } else if (currentAction === 'delete' && currentLeadId) {
    if (!deletedIds.includes(currentLeadId)) {
      deletedIds.push(currentLeadId);
      localStorage.setItem('outreach-deleted', JSON.stringify(deletedIds));
    }
    const card = document.getElementById('card-' + currentLeadId);
    if (card) {
      card.classList.add('deleted');
      setTimeout(() => {
        renderLeads();
        updateStats();
      }, 420);
    } else {
      renderLeads();
      updateStats();
    }
    closeModal();
  }
}

// ===== MOCK INBOX =====
function loadMockInbox() {
  if (currentMode !== 'test') return;

  fetch(API_BASE + '/api/mock-inbox', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: '{}'
  })
  .then(r => r.json())
  .then(data => {
    const items = data.items || [];
    document.getElementById('mockInboxCount').textContent = items.length + ' email' + (items.length !== 1 ? 's' : '');
    const container = document.getElementById('mockInboxItems');
    container.innerHTML = '';

    if (items.length === 0) {
      container.innerHTML = '<div class="mock-inbox-empty">📭 No emails in mock inbox yet. Send some test emails!</div>';
      return;
    }

    items.slice().reverse().forEach(item => {
      const div = document.createElement('div');
      div.className = 'mock-inbox-item';
      div.innerHTML = `
        <div class="mii-to">📧 ${item.to_name} &lt;${item.to_email}&gt;</div>
        <div class="mii-subject">${item.subject}</div>
        <div class="mii-meta">
          <span>📂 ${item.pipeline}</span>
          <span>🕐 ${item.sent_at}</span>
          <span>🧪 Test</span>
        </div>
        <div class="mii-body">${item.body}</div>
      `;
      container.appendChild(div);
    });
  })
  .catch(() => {});
}

function clearMockInbox() {
  if (!confirm('Clear all mock inbox emails?')) return;
  fetch(API_BASE + '/api/clear-mock-inbox', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: '{}'
  })
  .then(r => r.json())
  .then(data => {
    if (data.success) {
      loadMockInbox();
    }
  })
  .catch(() => {});
